    19	package org.apache.hadoop.hdfs.server.federation.fairness;
    20	
    21	import java.util.HashMap;
    22	import java.util.Map;
    23	import java.util.concurrent.Semaphore;
    24	import java.util.concurrent.TimeUnit;
    25	
    26	import org.apache.hadoop.conf.Configuration;
    27	import org.slf4j.Logger;
    28	import org.slf4j.LoggerFactory;
    29	
    30	/**
    31	 * Base fairness policy that implements @RouterRpcFairnessPolicyController.
    32	 * Internally a map of nameservice to Semaphore is used to control permits.
    33	 */
    34	public class AbstractRouterRpcFairnessPolicyController
    35	    implements RouterRpcFairnessPolicyController {
    36	
    37	  private static final Logger LOG =
    38	      LoggerFactory.getLogger(AbstractRouterRpcFairnessPolicyController.class);
    39	
    40	  /** Hash table to hold semaphore for each configured name service. */
    41	  private Map<String, Semaphore> permits;
    42	
    43	  public void init(Configuration conf) {
    44	    this.permits = new HashMap<>();
    45	  }
    46	
    47	  @Override
    48	  public boolean acquirePermit(String nsId) {
    49	    try {
    50	      LOG.debug("Taking lock for nameservice {}", nsId);
    51	      return this.permits.get(nsId).tryAcquire(1, TimeUnit.SECONDS);
    52	    } catch (InterruptedException e) {
    53	      LOG.debug("Cannot get a permit for nameservice {}", nsId);
    54	    }
    55	    return false;
    56	  }
    57	
    58	  @Override
    59	  public void releasePermit(String nsId) {
    60	    this.permits.get(nsId).release();
    61	  }
    62	
    63	  @Override
    64	  public void shutdown() {
    65	    // drain all semaphores
    66	    for (Semaphore sema: this.permits.values()) {
    67	      sema.drainPermits();
    68	    }
    69	  }
    70	
    71	  protected void insertNameServiceWithPermits(String nsId, int maxPermits) {
    72	    this.permits.put(nsId, new Semaphore(maxPermits));
    73	  }
    74	
    75	  protected int getAvailablePermits(String nsId) {
    76	    return this.permits.get(nsId).availablePermits();
    77	  }
    78	}
